//! Model catalog: per-provider model metadata from a models.dev-style
//! snapshot (opencode `models-dev.ts` pattern).
//!
//! The snapshot is a bundled JSON file (12 OpenAI-compatible providers,
//! ~650 models) with capability flags, context/output limits, pricing
//! and modality lists. `catalog_snapshot.json` is regenerated by
//! `script/update-catalog.py` (see docs in that file). Native builds may
//! refresh from the live URL behind `native-transport`; WASM uses the
//! snapshot only.
//!
//! Wire philosophy (matches the rest of the core): the snapshot is data,
//! not logic — a corrupt or partial snapshot degrades to "no metadata",
//! never to a failed request.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// Live catalog source (models.dev family). Refresh fetches this.
pub const CATALOG_URL: &str = "https://models.dev/api.json";

/// Input modality of a model.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Modality {
    Text,
    Image,
    Audio,
    Video,
    Pdf,
}

/// Model lifecycle status from the catalog.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ModelStatus {
    Alpha,
    Beta,
    Deprecated,
}

/// One model's metadata. All fields optional except identity so a
/// sparse snapshot still loads.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ModelInfo {
    pub id: String,
    #[serde(default)]
    pub name: String,
    /// Supports `<thinking>`-style reasoning output.
    #[serde(default)]
    pub reasoning: bool,
    /// Supports OpenAI-style tool calling.
    #[serde(default)]
    pub tool_call: bool,
    /// Accepts attachments (images/pdf) on the chat path.
    #[serde(default)]
    pub attachment: bool,
    /// Server honors the sampling temperature.
    #[serde(default = "default_true")]
    pub temperature: bool,
    /// Context window in tokens; None = unknown.
    #[serde(default)]
    pub limit_context: Option<u64>,
    /// Max output tokens; None = unknown.
    #[serde(default)]
    pub limit_output: Option<u64>,
    /// USD per million input tokens; None = unknown/free.
    #[serde(default)]
    pub cost_in: Option<f64>,
    /// USD per million output tokens.
    #[serde(default)]
    pub cost_out: Option<f64>,
    /// Input modalities (text implied for chat models).
    #[serde(default)]
    pub modalities_in: Vec<Modality>,
    #[serde(default)]
    pub status: Option<ModelStatus>,
    #[serde(default)]
    pub release_date: Option<String>,
}

fn default_true() -> bool {
    true
}

impl ModelInfo {
    /// True when the catalog marks this model deprecated.
    pub fn deprecated(&self) -> bool {
        self.status == Some(ModelStatus::Deprecated)
    }
}

/// Catalog entry for one provider: the models it lists plus the
/// OpenAI-compatible base URL its models are served on.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CatalogProvider {
    /// models.dev provider id (may differ from Prism's id).
    pub catalog_id: String,
    /// Base URL the models are reachable on (OpenAI-compatible).
    pub base_url: String,
    /// Env-var names that may carry the API key.
    #[serde(default)]
    pub env: Vec<String>,
    #[serde(default)]
    pub models: HashMap<String, ModelInfo>,
}

impl CatalogProvider {
    /// Newest non-deprecated chat model id, or None when the provider
    /// has no usable entries. Ties broken by id for determinism.
    pub fn default_model(&self) -> Option<&str> {
        self.models
            .values()
            .filter(|m| !m.deprecated())
            .max_by(|a, b| {
                a.release_date
                    .cmp(&b.release_date)
                    .then_with(|| a.id.cmp(&b.id))
            })
            .map(|m| m.id.as_str())
    }
}

/// The whole catalog, keyed by Prism provider id.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct Catalog {
    /// Prism provider id -> entry (e.g. "openai", "gemini").
    pub providers: HashMap<String, CatalogProvider>,
}

impl Catalog {
    /// Parse a catalog JSON document (snapshot or cache). Providers
    /// whose mapping is unknown are kept but inert.
    pub fn from_json(text: &str) -> Result<Catalog, serde_json::Error> {
        serde_json::from_str(text)
    }

    /// Look up one model's metadata.
    pub fn model(&self, provider: &str, model: &str) -> Option<&ModelInfo> {
        self.providers.get(provider)?.models.get(model)
    }

    /// Models for a provider, sorted by release date (newest first),
    /// deprecated last. Empty for unknown providers.
    pub fn models_for(&self, provider: &str) -> Vec<&ModelInfo> {
        let Some(p) = self.providers.get(provider) else {
            return Vec::new();
        };
        let mut v: Vec<&ModelInfo> = p.models.values().collect();
        v.sort_by(|a, b| {
            b.release_date
                .cmp(&a.release_date)
                .then_with(|| a.id.cmp(&b.id))
        });
        v.sort_by_key(|m| m.deprecated());
        v
    }
}

/// The bundled snapshot, compiled in. Always parseable (it ships with
/// the crate); on parse failure we degrade to an empty catalog rather
/// than panic — the client falls back to live model listing.
pub fn snapshot() -> Catalog {
    const SNAPSHOT: &str = include_str!("catalog_snapshot.json");
    Catalog::from_json(SNAPSHOT).unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn snapshot_parses_and_has_expected_providers() {
        let cat = snapshot();
        for id in [
            "openai",
            "gemini",
            "deepseek",
            "groq",
            "openrouter",
            "mistral",
            "grok",
            "nvidia-nim",
            "cerebras",
            "together",
            "fireworks",
            "perplexity",
        ] {
            assert!(cat.providers.contains_key(id), "missing {id}");
        }
        // At least a few hundred models total.
        let total: usize = cat.providers.values().map(|p| p.models.len()).sum();
        assert!(total >= 500, "expected large catalog, got {total}");
    }

    #[test]
    fn snapshot_provider_urls_are_absolute_https() {
        let cat = snapshot();
        for (id, p) in &cat.providers {
            assert!(
                p.base_url.starts_with("https://") || p.base_url.starts_with("http://"),
                "{id} base_url {p:?}"
            );
        }
    }

    #[test]
    fn default_model_prefers_newest_non_deprecated() {
        let p = CatalogProvider {
            catalog_id: "test".into(),
            base_url: "https://x.test".into(),
            env: vec![],
            models: [
                ("old", (None, None)),
                ("mid", (Some("2024-01-01"), None)),
                ("newest", (Some("2025-06-01"), None)),
                ("newest-deprecated", (Some("2025-08-01"), Some(ModelStatus::Deprecated))),
            ]
            .into_iter()
            .map(|(id, (date, status))| {
                (
                    id.to_string(),
                    ModelInfo {
                        id: id.to_string(),
                        name: id.into(),
                        reasoning: false,
                        tool_call: true,
                        attachment: false,
                        temperature: true,
                        limit_context: None,
                        limit_output: None,
                        cost_in: None,
                        cost_out: None,
                        modalities_in: vec![],
                        status,
                        release_date: date.map(String::from),
                    },
                )
            })
            .collect(),
        };
        assert_eq!(p.default_model(), Some("newest"));
    }

    #[test]
    fn models_for_sorts_newest_first_deprecated_last() {
        let mut cat = Catalog::default();
        let p = CatalogProvider {
            catalog_id: "test".into(),
            base_url: "https://x.test".into(),
            env: vec![],
            models: [
                ("a-old", "2024-01-01", None),
                ("b-new", "2025-01-01", None),
                ("c-dep", "2025-06-01", Some(ModelStatus::Deprecated)),
            ]
            .into_iter()
            .map(|(id, date, status)| {
                (
                    id.to_string(),
                    ModelInfo {
                        id: id.to_string(),
                        name: id.into(),
                        reasoning: false,
                        tool_call: false,
                        attachment: false,
                        temperature: true,
                        limit_context: None,
                        limit_output: None,
                        cost_in: None,
                        cost_out: None,
                        modalities_in: vec![],
                        status,
                        release_date: Some(date.into()),
                    },
                )
            })
            .collect(),
        };
        cat.providers.insert("test".into(), p);
        let names: Vec<&str> = cat.models_for("test").iter().map(|m| m.id.as_str()).collect();
        assert_eq!(names, vec!["b-new", "a-old", "c-dep"]);
    }

    #[test]
    fn sparse_entries_load_with_defaults() {
        let cat = Catalog::from_json(
            r#"{"providers":{"openai":{"catalog_id":"openai","base_url":"https://api.openai.com/v1","models":{"x":{"id":"x"}}}}}"#,
        )
        .unwrap();
        let m = cat.model("openai", "x").unwrap();
        assert!(m.temperature, "temperature defaults true");
        assert!(!m.reasoning);
        assert_eq!(m.limit_context, None);
    }

    #[test]
    fn corrupt_snapshot_degrades_to_empty_not_panic() {
        let cat = Catalog::from_json("{not json").unwrap_or_default();
        assert!(cat.providers.is_empty());
    }
}
